 public static void Main(string[] args){var d=SubtitleDocument.Load(args[0]);d.Validate();if(d.Pipeline!="v148-verified-1"||d.Cues.Count!=87||d.ReviewCount!=49||d.Audit.Elements("change").Count()!=4)throw new Exception("Production XML/metadata mismatch");string dir=Path.Combine(Path.GetTempPath(),"v15-real-148-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string media=Path.Combine(dir,"Wild Night Out P1 - Mr Ballen New Episode.mp4");File.WriteAllText(media,"untouched media fixture");string first=d.ExportBeside(media),second=d.ExportBeside(media);if(Path.GetFileName(first)!="Wild Night Out P1 - Mr Ballen New Episode.srt"||Path.GetFileName(second)!="Wild Night Out P1 - Mr Ballen New Episode_2.srt")throw new Exception("Adjacent export failed");if(!File.ReadAllText(first).Contains("playing pool")||File.ReadAllText(first).Contains("playing playing"))throw new Exception("SRT wording mismatch");d.Save(Path.Combine(dir,"saved.xml"));var loaded=SubtitleDocument.Load(Path.Combine(dir,"saved.xml"));if(loaded.ReviewCount!=49||loaded.Audit.Elements("change").Count()!=4||!loaded.Cues.Any(c=>!String.IsNullOrEmpty(c.Info)))throw new Exception("Saved metadata lost");foreach(string p in args.Skip(1))SubtitleDocument.Load(p).Validate();Console.WriteLine("PASS real video 87 cues, 49 pending, 4 audited edits, original basename, non-overwriting SRT, pipeline/audit/info round-trip and all real media XML fixtures");}
